import sys

# Parse symbols
syms = []
with open('symbols/dynsyms.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            name = parts[2]
            syms.append((addr, name))
syms.sort()

# Target addresses
targets = [0x222098, 0x2241ac, 0x1abc80, 0x1abd14, 0x16dfa4, 0x16db6c, 0x16de04]

for t in targets:
