    for addr, name in syms:
        if addr <= t:
            best = (addr, name)
        else:
            break
    if best:
        offset = t - best[0]
        print(f'  0x{t:08x}: {best[1]}+0x{offset:x}')
    else:
        print(f'  0x{t:08x}: ???')
